package com.ruoyi.framework.audit;
import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import org.springframework.jdbc.core.JdbcTemplate;import com.ruoyi.metal.security.FactoryScope;import com.ruoyi.common.exception.ServiceException;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class LogActorFilterTest {
 @Test void actorIdIsExactAndFactoryVisibilityStillApplies(){var jdbc=mock(JdbcTemplate.class);var scope=mock(FactoryScope.class);when(scope.currentFactory()).thenReturn(43L);when(jdbc.queryForObject(anyString(),eq(Long.class),any(Object[].class))).thenReturn(0L);var service=new LogQueryService(jdbc,scope);service.list("operation",Map.of("actorId","165"),false);var query=ArgumentCaptor.forClass(String.class);var args=ArgumentCaptor.forClass(Object[].class);verify(jdbc).queryForObject(query.capture(),eq(Long.class),args.capture());assertTrue(query.getValue().contains("actor_user_id=?"));assertTrue(query.getValue().contains("business_factory_id=?"));assertTrue(query.getValue().contains("NOT EXISTS"));assertEquals(165L,args.getValue()[args.getValue().length-1]);}
 @Test void actorOptionsUseRoleNamePhoneAndLiteralSearchWithinVisibleFactory(){var jdbc=mock(JdbcTemplate.class);var scope=mock(FactoryScope.class);when(scope.currentFactory()).thenReturn(43L);var service=new LogQueryService(jdbc,scope);service.actorOptions("管理员_%",null,2);var query=ArgumentCaptor.forClass(String.class);var args=ArgumentCaptor.forClass(Object[].class);verify(jdbc).queryForList(query.capture(),args.capture());assertTrue(query.getValue().contains("role_name"));assertTrue(query.getValue().contains("nick_name"));assertTrue(query.getValue().contains("phonenumber"));assertTrue(query.getValue().contains("business_factory_id=?"));assertTrue(query.getValue().contains("NOT EXISTS"));assertTrue(query.getValue().contains("ESCAPE '!'"));assertEquals(List.of(43L,43L,43L,"%管理员!_!%%",20),Arrays.asList(args.getValue()));}
 @Test void candidatesArePagedAndReportMore(){var jdbc=mock(JdbcTemplate.class);var scope=mock(FactoryScope.class);when(scope.currentFactory()).thenReturn(43L);var rows=new ArrayList<Map<String,Object>>();for(int i=0;i<21;i++)rows.add(Map.of("id",""+i,"name","人员"+i));when(jdbc.queryForList(anyString(),any(Object[].class))).thenReturn(rows);var result=new LogQueryService(jdbc,scope).actorOptions("",null,1);assertEquals(20,((List<?>)result.get("rows")).size());assertEquals(true,result.get("hasMore"));}
 @Test void rejectsCrossFactoryOptionsAndInvalidInputs(){var jdbc=mock(JdbcTemplate.class);var scope=mock(FactoryScope.class);when(scope.currentFactory()).thenReturn(43L);doThrow(new ServiceException("无权访问",403)).when(scope).check(99L);var service=new LogQueryService(jdbc,scope);assertThrows(ServiceException.class,()->service.actorOptions("",99L,1));assertThrows(ServiceException.class,()->service.actorOptions("",null,0));assertThrows(ServiceException.class,()->service.actorOptions("x".repeat(101),null,1));for(String id:List.of("-1","x","9223372036854775808"))assertThrows(ServiceException.class,()->service.list("operation",Map.of("actorId",id),false));}
 @Test void loginIdentityDoesNotDependOnCurrentPhone(){var jdbc=mock(JdbcTemplate.class);var scope=mock(FactoryScope.class);when(jdbc.queryForObject(anyString(),eq(Long.class),any(Object[].class))).thenReturn(0L);new LogQueryService(jdbc,scope).list("login",Map.of("actorId","165"),false);var query=ArgumentCaptor.forClass(String.class);var args=ArgumentCaptor.forClass(Object[].class);verify(jdbc).queryForObject(query.capture(),eq(Long.class),args.capture());assertTrue(query.getValue().contains("account_user_id=?"));assertFalse(query.getValue().contains("user_name IN"));assertEquals(165L,args.getValue()[2]);verify(jdbc,never()).queryForList(eq("SELECT user_name FROM sys_user WHERE user_id=?"),anyLong());verify(scope).adminOnly();}
 @Test void loginOptionsRequireExistingAdminScope(){var jdbc=mock(JdbcTemplate.class);var scope=mock(FactoryScope.class);doThrow(new ServiceException("无权访问",403)).when(scope).adminOnly();assertThrows(ServiceException.class,()->new LogQueryService(jdbc,scope).loginActorOptions("",1));verifyNoInteractions(jdbc);}
 @Test void loginOptionsCanSearchFormerPeopleAndReturnPage(){var jdbc=mock(JdbcTemplate.class);var scope=mock(FactoryScope.class);when(jdbc.queryForList(anyString(),any(Object[].class))).thenReturn(List.of(Map.of("id","165","name","审核员｜张三｜13812345678")));var result=new LogQueryService(jdbc,scope).loginActorOptions("张三",1);assertEquals(1,((List<?>)result.get("rows")).size());assertEquals(false,result.get("hasMore"));verify(scope).adminOnly();}
 @Test void associationFilterIsSharedByListAndExport(){for(boolean export:List.of(false,true)){var j=mock(JdbcTemplate.class);when(j.queryForObject(anyString(),eq(Long.class),any(Object[].class))).thenReturn(0L);new LogQueryService(j,mock(FactoryScope.class)).list("login",Map.of("associationStatus","HISTORICAL"),export);var q=ArgumentCaptor.forClass(String.class);verify(j).queryForObject(q.capture(),eq(Long.class),any(Object[].class));assertTrue(q.getValue().contains("historical_max_id"));assertTrue(q.getValue().contains("migration_time"));}assertThrows(ServiceException.class,()->new LogQueryService(mock(JdbcTemplate.class),mock(FactoryScope.class)).list("login",Map.of("associationStatus","BAD"),false));}
}
